// Once-daily upload of everything on the SD card to MinIO. Polled from
// networkTask; the SD directory itself is the handoff from audio_capture —
// no "file ready" signal is needed, a daily scan is sufficient.
#pragma once

namespace upload_scheduler {

void begin();

// Call periodically (e.g. every kSchedulerPollIntervalMs) from networkTask.
// Fires run_upload_pass() once per day at kUploadHour local time, plus one
// pass right after the first successful NTP sync (closes the gap where a
// reboot near the upload hour would otherwise wait a full day).
void tick();

} // namespace upload_scheduler
#include "upload_scheduler.h"

#include <Arduino.h>

#include "config.h"
#include "ntp_time.h"
#include "s3_uploader.h"
#include "sd_storage.h"

namespace upload_scheduler {

namespace {
bool g_uploaded_today = false;
bool g_boot_catchup_done = false;
} // namespace

void begin() {
  g_uploaded_today = false;
  g_boot_catchup_done = false;
}

namespace {

void run_upload_pass() {
  if (!sd_storage::lock()) {
    return;
  }

  const auto recordings = sd_storage::list_recordings();
  Serial.printf("upload: pass started, %u file(s)\n",
                static_cast<unsigned>(recordings.size()));
  for (const auto &path : recordings) {
    if (s3_uploader::upload_file(path)) {
      sd_storage::remove_file(path);
    }
    // On failure, leave the file in place — retried on the next pass.
  }

  sd_storage::unlock();
}

} // namespace

void tick() {
  if (!ntp_time::is_synced()) {
    return;
  }

  if (!g_boot_catchup_done) {
    g_boot_catchup_done = true;
    run_upload_pass(); // no-op if nothing to upload
  }

  tm t = ntp_time::local_now();
  if (t.tm_hour == kUploadHour) {
    if (!g_uploaded_today) {
      run_upload_pass();
      g_uploaded_today = true;
    }
  } else {
    g_uploaded_today = false; // re-arm once we leave the upload hour
  }
}

} // namespace upload_scheduler
// XIAO ESP32S3 Sense doorbell recorder.
//
// Scope: (1) MQTT-triggered recording to SD, (2) once-daily upload of the SD
// card's contents to MinIO. No cross-correlation detection, no on-device ML,
// no camera use — see firmware/esp32-sense/README.md and the project plan
// this was built from.
//
// Concurrency: Arduino's loop() already runs as its own FreeRTOS task
// (pinned to core 1 by default) — that's where audio_capture lives, so it
// spawns no task of its own. One extra task, networkTask (core 0), services
// WiFi/MQTT and the daily upload scheduler.
#include <Arduino.h>
#include <WiFi.h>

#include <cstring>
#include <ctime>

#include "audio_capture.h"
#include "mqtt_client.h"
#include "ntp_time.h"
#include "ota.h"
#include "sd_storage.h"
#include "upload_scheduler.h"
#include "wifi_manager.h"

namespace {

void network_task(void *) {
  wifi_manager::begin();
  mqtt_client::begin();
  upload_scheduler::begin();

  bool ntp_started = false;
  bool was_connected = false;
  bool was_synced = false;

  for (;;) {
    wifi_manager::maybe_reconnect();

    const bool connected = wifi_manager::is_connected();
    if (connected != was_connected) {
      was_connected = connected;
      if (connected) {
        Serial.printf("wifi: connected, ip %s\n",
                      WiFi.localIP().toString().c_str());
      } else {
        Serial.println("wifi: disconnected");
      }
    }
    if (!was_synced && ntp_time::is_synced()) {
      was_synced = true;
      tm t = ntp_time::local_now();
      char stamp[32];
      std::strftime(stamp, sizeof(stamp), "%Y-%m-%d %H:%M:%S", &t);
      Serial.printf("ntp: synced, local time %s\n", stamp);
    }

    if (connected) {
      if (!ntp_started) {
        ntp_time::sync();
        ntp_started = true;
      } else {
        ntp_time::maybe_resync();
      }

      mqtt_client::loop_tick();
      upload_scheduler::tick();
    }
    // Outside the connected branch: a new image that never gets online must
    // still hit its confirmation timeout and roll back.
    ota::tick();

    vTaskDelay(pdMS_TO_TICKS(100));
  }
}

} // namespace

void setup() {
  Serial.begin(115200);
  ntp_time::apply_tz();
  ota::begin();

  if (!sd_storage::begin()) {
    Serial.println("FATAL: SD card init failed");
    ota::roll_back_if_unconfirmed();
    while (true) {
      delay(1000);
    }
  }

  if (!audio_capture::begin()) {
    Serial.println(
        "FATAL: audio_capture init failed (PSRAM or I2S/PDM mic)");
    ota::roll_back_if_unconfirmed();
    while (true) {
      delay(1000);
    }
  }

  // Core 0 for networking, matching the design's split from Arduino's
  // loop()/core 1 running the audio capture path.
  xTaskCreatePinnedToCore(network_task, "networkTask", 8192, nullptr, 1,
                          nullptr, 0);

  // An IANA name like "Europe/Berlin" is not understood by newlib and is
  // silently treated as UTC; a POSIX TZ string always carries an offset digit.
  const bool tz_has_offset = std::strpbrk(TZ_STRING, "0123456789") != nullptr;
  Serial.printf("tz: \"%s\"%s\n", TZ_STRING,
                tz_has_offset ? ""
                              : " -- not a POSIX TZ string, local time is UTC");

  Serial.println("Doorbell recorder ready.");
}

void loop() { audio_capture::loop_tick(); }
